// Decide whether a human must know. No items returned = no message (all is well).
// Messages go out in Telegram HTML mode: escape <, > and & so any name is shown as is.
const html = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const tz = 'Europe/Madrid';
const fmt = (iso) => (iso ? DateTime.fromISO(iso).setZone(tz).toFormat("yyyy-MM-dd HH:mm 'Madrid'") : 'never');
const now = DateTime.now().setZone(tz).toFormat("yyyy-MM-dd HH:mm 'Madrid'");
const res = $input.first().json;

if (res.statusCode === undefined) {
  // The request itself failed (API down, timeout): arrived through the error output.
  const reason = res.error?.message ?? JSON.stringify(res).slice(0, 300);
  return [{ json: { text: html(`🚨 AccessOps cleanup could not run (${now}).\n${reason}`) } }];
}
if (res.statusCode === 409) return []; // another cleanup is still running: nothing wrong
if (res.statusCode !== 200) {
  const detail = JSON.stringify(res.body).slice(0, 300);
  return [{ json: { text: html(`🚨 AccessOps cleanup failed: HTTP ${res.statusCode} (${now}).\n${detail}`) } }];
}
const errors = res.body.errors ?? [];
if (errors.length === 0) return [];
const lines = errors.map(
  (e) => `• ${e.subject} in ${e.system} (role ${e.role}, expired ${fmt(e.expires_at)}): ${e.error}`,
);
return [{
  json: {
    text: html(`🚨 AccessOps cleanup: ${errors.length} revoke(s) failed (${now}).\n` +
      `This access is still active; the next run (in 5 min) tries again.\n${lines.join('\n')}`),
  },
}];

// Decide whether a human must know. No items returned = no message (all is well).
// Messages go out in Telegram HTML mode: escape <, > and & so any name is shown as is.
const html = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const tz = 'Europe/Madrid';
const now = DateTime.now().setZone(tz).toFormat("yyyy-MM-dd HH:mm 'Madrid'");
const res = $input.first().json;

if (res.statusCode === undefined) {
  const reason = res.error?.message ?? JSON.stringify(res).slice(0, 300);
  return [{ json: { text: html(`🚨 AccessOps drift check could not run (${now}).\n${reason}`) } }];
}
if (res.statusCode !== 200) {
  const detail = JSON.stringify(res.body).slice(0, 300);
  return [{ json: { text: html(`🚨 AccessOps drift check failed: HTTP ${res.statusCode} (${now}).\n${detail}`) } }];
}

const out = [];
const problems = res.body.problems ?? [];
if (problems.length > 0) {
  const describe = (p) => {
    if (p.category === 'extra') return `has AccessOps role ${p.actual_role} but no grant`;
    if (p.category === 'missing') return `granted role ${p.expected_role} but the account is missing`;
    return `role is ${p.actual_role}, grant says ${p.expected_role}`;
  };
  const lines = problems.map((p) => `• [${p.category}] ${p.subject} in ${p.system}: ${describe(p)}`);
  out.push({
    json: {
      text: html(`🚨 AccessOps drift: ${problems.length} problem(s) (${now}).\n${lines.join('\n')}\n` +
        'Details: python -m accessops report drift'),
    },
  });
}

// Accounts not managed by AccessOps: only report CHANGES. The last list is remembered
// between scheduled runs (n8n saves static data for active workflows, not manual runs).
const state = $getWorkflowStaticData('global');
const current = (res.body.foreign ?? []).map((f) => `${f.system}:${f.subject}`).sort();
if (state.foreign === undefined) {
  state.foreign = current; // first run: remember the list, no message
} else {
  const added = current.filter((x) => !state.foreign.includes(x));
  const removed = state.foreign.filter((x) => !current.includes(x));
  if (added.length > 0 || removed.length > 0) {
    const parts = [`ℹ️ AccessOps: accounts outside AccessOps changed (${now}).`];
    if (added.length > 0) parts.push(`New: ${added.join(', ')}`);
    if (removed.length > 0) parts.push(`Gone: ${removed.join(', ')}`);
    parts.push('AccessOps never touches them. If this was expected, nothing to do.');
    out.push({ json: { text: html(parts.join('\n')) } });
  }
  state.foreign = current;
}
return out;
